using System.Collections.Generic;public class Solution{Dictionary<string,List<string>>pre=new();List<IList<string>>o=new();void Dfs(string w,string b,List<string>p){p.Add(w);if(w==b){var v=new List<string>(p);v.Reverse();o.Add(v);}else if(pre.ContainsKey(w))foreach(var x in pre[w])Dfs(x,b,p);p.RemoveAt(p.Count-1);}public IList<IList<string>> FindLadders(string b,string e,IList<string>wl){var dict=new HashSet<string>(wl);if(!dict.Contains(e))return o;var q=new Queue<string>();var d=new Dictionary<string,int>();q.Enqueue(b);d[b]=0;while(q.Count>0){var w=q.Dequeue();int nd=d[w]+1;var a=w.ToCharArray();for(int i=0;i<a.Length;i++){char old=a[i];for(char c='a';c<='z';c++){a[i]=c;var x=new string(a);if(dict.Contains(x)){if(!d.ContainsKey(x)){d[x]=nd;q.Enqueue(x);}if(d[x]==nd){if(!pre.ContainsKey(x))pre[x]=new();pre[x].Add(w);}}}a[i]=old;}}if(d.ContainsKey(e))Dfs(e,b,new List<string>());return o;}}
